// Tests the highlight.js language the documentation site uses (docs/book/theme/bezel-highlight.js,
// generated by scripts/gen_editor_grammars.py) under highlight.js 10.1.1, the version mdBook 0.4.52
// bundles. It (1) highlights every ```bezel block in docs/*.md and fails on a thrown error, an
// `illegal` result or a block that ends inside a mode (an unclosed string, comment or context),
// and (2) checks the contextual-keyword fixtures of test/contextual-fixtures.js: every «word» must
// be inside a `hljs-keyword` span, every ‹word› outside any keyword span, and every ⟪code⟫
// outside any string or comment span.
// Usage (from editors/vscode):
//   npm install --no-save highlight.js@10.1.1
//   node test/hljs.js
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const { parse } = require('./contextual-parse');

const root = path.resolve(__dirname, '..', '..', '..');
const hljs = require('highlight.js/lib/core');
if (!/^10\./.test(hljs.versionString)) {
  console.error(`expected highlight.js 10.x (mdBook's bundled copy), found ${hljs.versionString}`);
  process.exit(2);
}
// The generated file registers the language on the global `hljs`, then re-highlights the page's
// code.language-bezel blocks; give it an empty page.
const src = fs.readFileSync(path.join(root, 'docs', 'book', 'theme', 'bezel-highlight.js'), 'utf8');
vm.runInNewContext(src, { hljs, document: { querySelectorAll: () => [] } });
if (!hljs.getLanguage('bezel')) { console.error('bezel-highlight.js registered no `bezel` language'); process.exit(1); }

// Debug mode makes highlight.js throw where the site's safe mode would log and fall back to plain
// text (a zero-width match loop, a bad regex); illegal matches are reported, not ignored.
hljs.debugMode();
const highlight = (code) => {
  const r = hljs.highlight('bezel', code, false);   // ignore_illegals = false
  if (r.errorRaised) throw r.errorRaised;
  return r;
};
// The text offsets [start, end) of every span with one of the classes in highlight.js HTML.
function spanRanges(html, classes) {
  const ranges = [], stack = [];
  let pos = 0;
  const re = /<span class="([^"]*)">|<\/span>|&(amp|lt|gt|quot|#x27|#39);|[^<&]+/g;
  let m;
  while ((m = re.exec(html))) {
    if (m[1] !== undefined) stack.push({ cls: m[1], start: pos });
    else if (m[0] === '</span>') {
      const s = stack.pop();
      if (s.cls.split(' ').some((c) => classes.includes(c))) ranges.push([s.start, pos]);
    } else if (m[2] !== undefined) pos += 1;
    else pos += m[0].length;
  }
  return ranges;
}

let blocks = 0;
const bad = [];
for (const f of fs.readdirSync(path.join(root, 'docs')).filter((n) => n.endsWith('.md'))) {
  const text = fs.readFileSync(path.join(root, 'docs', f), 'utf8');
  const re = /^```bezel\n([\s\S]*?)^```/gm;
  let m;
  while ((m = re.exec(text))) {
    blocks++;
    const at = `${f}:${text.slice(0, m.index).split('\n').length}`;
    try {
      const r = highlight(m[1]);
      if (r.illegal) bad.push(`${at}: illegal`);
      // a block must end back at the top level, not inside a string, comment or context mode
      else if (r.top && r.top.parent) bad.push(`${at}: ends inside a mode (${r.top.className || r.top.begin})`);
    } catch (e) {
      bad.push(`${at}: ${e.message}`);
    }
  }
}

let checked = 0;
for (const fixture of require('./contextual-fixtures')) {
  const { code, marks } = parse(fixture);
  let ranges, quoted;
  try {
    const r = highlight(code);
    if (r.illegal) { bad.push(`${JSON.stringify(fixture)}: illegal`); continue; }
    ranges = spanRanges(r.value, ['hljs-keyword']);
    quoted = spanRanges(r.value, ['hljs-string', 'hljs-comment']);
  } catch (e) {
    bad.push(`${JSON.stringify(fixture)}: ${e.message}`);
    continue;
  }
  for (const mk of marks) {
    checked++;
    if (mk.kind === 'code') {
      if (quoted.some(([s, e]) => s < mk.end && mk.start < e)) {
        bad.push(`${JSON.stringify(fixture)}: \`${mk.word}\` at ${mk.start} is inside a string or comment`);
      }
      continue;
    }
    const inKw = ranges.some(([s, e]) => s <= mk.start && mk.end <= e);
    const touchesKw = ranges.some(([s, e]) => s < mk.end && mk.start < e);
    if (mk.keyword ? !inKw : touchesKw) {
      bad.push(`${JSON.stringify(fixture)}: \`${mk.word}\` at ${mk.start} should ` +
               (mk.keyword ? '' : 'not ') + 'be a keyword');
    }
  }
}
console.log(`highlighted ${blocks} bezel blocks with highlight.js ${hljs.versionString}; ` +
            `checked ${checked} contextual positions`);
if (bad.length) {
  console.log(`${bad.length} problem(s):`);
  for (const b of bad.slice(0, 60)) console.log('  ' + b);
  process.exit(1);
}
